def _run(agent, state, events):
    kind = agent["kind"]

    if kind == "worker":
        value, escalate = agent["fn"](state)
        key = agent.get("output_key")
        if key is not None:
            state[key] = value
        events.append({"agent": agent["name"], "wrote": key, "value": value})
        return bool(escalate)

    if kind == "sequential":
        for child in agent["children"]:
            if _run(child, state, events):
                return True
        return False

    if kind == "parallel":
        keys = [c.get("output_key") for c in agent["children"]
                if c.get("output_key") is not None]
        clashing = {k for k in keys if keys.count(k) > 1}
        if clashing:
            raise ValueError(
                f"parallel children share output_key {sorted(clashing)!r}")
        escalated = False
        for child in agent["children"]:
            escalated = _run(child, state, events) or escalated
        return escalated

    if kind == "loop":
        limit = agent.get("max_iterations", 10)
        for i in range(1, limit + 1):
            for child in agent["children"]:
                if _run(child, state, events):
                    events.append({"agent": agent["name"], "stopped_at": i})
                    return False
        return False

    raise ValueError(f"unknown agent kind: {kind}")


def run_turn(agent, state):
    events = []
    _run(agent, state, events)
    for key in [k for k in state if k.startswith("temp:")]:
        del state[key]
    return events
